[184] = { en = "Furlbrow's Deed", tier = 1,
  t = "De akte van Furlbrow",
  d = "Dit is de eigendomsakte van een stuk landbouwgrond in Westfall. Een zekere Theodore Furlbrow heeft hem getekend, en zijn vrouw Verna heeft ook getekend. Op de achterkant van de akte staan snel neergekrabbelde woorden:$B$B\"We hebben Furlbrow onder druk gezet en zijn akte gekregen. We dachten dat het handig kon zijn, als je er een wilt vervalsen voor je eigen plek.$B$BDe Furlbrows geven ons geen last. Toen ik ze voor het laatst zag, waren ze Westfall aan het verlaten. Ze zaten vast met een kapotte wagen.\"$B$BJe denkt dat de Furlbrows hun akte misschien terug willen...",
  o = "Breng Furlbrow's Deed naar Farmer Furlbrow.",
  p = "Heb jij de akte van mijn boerderij?? Dat is goed nieuws! Een paar boeven hebben hem dagen geleden gestolen... Ik dacht dat hij voor altijd weg was!$b$bAlsjeblieft, geef hem aan mij. We gaan weg uit Westfall en we komen niet snel terug. Maar als we wel terugkomen, hebben we die papieren nodig...",
  c = "Heel erg bedankt, $N! Zoals ik al zei: deze streek is niet meer geschikt voor eerlijke mensen. Maar als het beter wordt, kunnen we met deze akte ons land terugkrijgen.$b$bIk heb niet veel om je te geven, maar hier -- neem dit.",
  g = { {"akte", "deed"}, {"eigendomsakte", "title deed"}, {"landbouwgrond", "farmland"}, {"Een zekere", "a certain"}, {"getekend", "signed (tekenen)"}, {"neergekrabbelde", "scrawled (neerkrabbelen)"}, {"onder druk gezet", "pressured, leaned on (onder druk zetten)"}, {"vervalsen", "to forge, fake"}, {"geven ons geen last", "won't give us trouble (last geven)"}, {"zaten vast", "were stuck (vastzitten)"}, {"boeven", "crooks, ruffians (boef)"}, {"streek", "region, parts"}, {"geschikt", "suitable, fit"}, {"eerlijke", "honest (eerlijk)"} },
},

[36] = { en = "Westfall Stew", tier = 1,
  t = "Stoofpot uit Westfall",
  d = "Ik had nooit gedacht dat ik de boerderij zou verlaten. Maar de velden zitten vol dieven, en het is hier nu veel te gevaarlijk voor ons. Als Farmer Furlbrow de wagen heeft gemaakt, gaan we weg.$b$bMisschien kun je me een plezier doen? Ik schrijf even snel mijn recept voor Westfall Stew op. Breng het alsjeblieft naar Salma Saldean, op de boerderij daarginds. De boerderij van de Saldeans ligt net voorbij de splitsing in de weg.",
  o = "Verna Furlbrow wil dat je haar recept voor Westfall Stew bezorgt bij Salma Saldean.",
  p = "Ik ga Verna Furlbrow zo erg missen. Heb je haar toevallig gezien, onderweg hierheen?",
  c = "Die Verna was altijd zo'n lieve meid. We gaan haar hier in Westfall missen. Maar onder ons gezegd: ze is diep vanbinnen een stadsmeisje. Stormwind past prima bij haar. Maar genoeg geroddeld! Nu kunnen we Westfall Stew maken!",
  g = { {"Stoofpot", "stew"}, {"verlaten", "to leave"}, {"een plezier doen", "to do a favour"}, {"recept", "recipe"}, {"daarginds", "over there, yonder"}, {"splitsing", "fork (in the road)"}, {"bezorgt", "deliver (bezorgen)"}, {"toevallig", "by chance"}, {"onder ons gezegd", "between you and me"}, {"vanbinnen", "inside, at heart"}, {"stadsmeisje", "city girl"}, {"past prima bij", "suits ... fine (passen bij)"}, {"geroddeld", "gossiped (roddelen)"} },
},

[6181] = { en = "A Swift Message", tier = 1,
  t = "Een snel bericht",
  d = "We krijgen niet veel directe hulp uit Stormwind. Maar ik heb wel een contact in de stad. Hij helpt ons aan harnassen. Hij heet Osric Strang. Zijn winkel, Limited Immunity, is in de Old Town van Stormwind.$B$BOnze voorraad harnassen wordt steeds kleiner. Ik moet Osric om meer vragen. Kun je hem dit briefje brengen?$B$BDe snelste weg naar Stormwind is via Thor, onze griffioenmeester. Hij staat net onderaan de heuvel. Breng hem mijn briefje en neem dan een griffioen naar Stormwind.",
  o = "Breng Lewis' Note naar Thor, de griffioenmeester.",
  p = "Je ziet eruit alsof je haast hebt. Nou, dan ben je hier aan het goede adres!",
  c = "Moet je dit briefje naar Stormwind brengen? Geen probleem, je kunt een van mijn griffioenen nemen!",
  g = { {"bericht", "message"}, {"directe", "direct (direct)"}, {"harnassen", "armor, suits of armor (harnas)"}, {"voorraad", "supply, stock"}, {"briefje", "note (brief)"}, {"griffioenmeester", "gryphon master"}, {"onderaan", "at the bottom of"}, {"heuvel", "hill"}, {"haast", "hurry"}, {"aan het goede adres", "in the right place"} },
},

[6261] = { en = "Dungar Longdrink", tier = 1,
  t = "Dungar Longdrink",
  d = "$N, ik heb alles wat Lewis vroeg in deze kist gedaan. Kun je die naar hem brengen?$B$BHeb je al met Thor in Westfall gepraat? Dan kun je met een griffioen terug naar hem vliegen. Dungar Longdrink is onze griffioenmeester. Hij staat in de Trade District.$B$BPraat met Dungar en breng deze kist dan zo snel mogelijk naar Lewis. We willen niet dat onze vechtende mannen en vrouwen in Westfall zonder nieuwe uitrusting zitten!",
  o = "Breng Osric's Crate naar Dungar Longdrink, de griffioenmeester.",
  p = "Is dat zweet op je voorhoofd, $gjongen:mevrouw;? Je hebt te veel gerend. Neem de volgende keer een griffioen!",
  c = "Een kist voor Westfall, hè? Ben je al eens in Westfall geweest? Als dat zo is, is het geen probleem, vriend. Ik heb genoeg griffioenen. Ze zijn getraind om die route te vliegen!",
  g = { {"kist", "crate"}, {"griffioen", "gryphon"}, {"zo snel mogelijk", "as fast as possible"}, {"vechtende", "fighting (vechten)"}, {"uitrusting", "equipment, gear"}, {"zweet", "sweat"}, {"voorhoofd", "forehead, brow"}, {"gerend", "run (rennen)"}, {"getraind", "trained (trainen)"} },
},

[6281] = { en = "Continue to Stormwind", tier = 1,
  t = "Verder naar Stormwind",
  d = "Voor een klein bedrag kun je met een griffioen naar Stormwind vliegen. Dan kun je het briefje van Lewis aan Osric geven. Op een andere manier kom je er niet sneller.$B$BVind je dat goed? Praat dan nog een keer met me als je klaar bent voor de vlucht. Ik vraag er een beetje geld voor, maar geloof me: het is het waard!",
  o = "Koop een griffioenvlucht bij griffioenmeester Thor. Breng daarna Lewis' Note naar Osric Strang, in de winkel Limited Immunity, in de Old Town van Stormwind.",
  p = "Je bent op reis geweest, hè? Ben je ergens interessants geweest?",
  c = "Ah, een briefje van Quartermaster Lewis? Het verbaast me niet dat hij meer spullen nodig heeft. Sentinel Hill is ver weg, in een land dat Stormwind bijna vergeten is.$B$BNou, dank je, $N. Hier is wat geld voor je reiskosten.",
  g = { {"bedrag", "amount (of money), fee"}, {"vlucht", "flight, ride"}, {"het is het waard", "it's worth it"}, {"griffioenvlucht", "gryphon ride"}, {"interessants", "interesting (after iets/ergens: interessant)"}, {"Het verbaast me niet", "it doesn't surprise me (verbazen)"}, {"spullen", "stuff, gear"}, {"vergeten", "forgotten"}, {"reiskosten", "travel costs"} },
},

[6285] = { en = "Return to Lewis", tier = 1,
  t = "Terug naar Lewis",
  d = "De griffioenmeester in Westfall is Thor. Heb je al eens met hem gepraat? Dan kun je met een van mijn griffioenen naar hem vliegen.$B$BDat is een goede les om te onthouden: griffioenen zijn altijd getraind om naar hun hoofdstad te vliegen. Maar naar een verre griffioenmeester brengen ze je pas als je daar al eens bent geweest.$B$BJe bent al bij Thor geweest. Praat dus nog een keer met me als je klaar bent om met een griffioen naar Westfall te vliegen. Daar kun je Osric's Crate aan Quartermaster Lewis geven.",
  o = "Koop een griffioenvlucht naar Sentinel Hill bij griffioenmeester Dungar Longdrink. Breng daarna Osric's Crate naar Lewis op Sentinel Hill.",
  p = "Ben je terug uit Stormwind? Heeft Osric de harnassen gestuurd?",
  c = "Mooi, je hebt de harnassen meegebracht! We verdelen ze meteen onder de mensen die ze nodig hebben.$B$BDank je, $N. Je hebt ons heel goed geholpen. En nu je griffioenen kent, hoop ik dat je vaak terugkomt om Sentinel Hill te helpen!",
  g = { {"onthouden", "to remember"}, {"hoofdstad", "capital city"}, {"verre", "remote, far (ver)"}, {"pas", "only (then), not until"}, {"griffioenvlucht", "gryphon ride"}, {"harnassen", "armor (harnas)"}, {"verdelen", "divide, hand out"}, {"meteen", "immediately"} },
},

[6721] = { en = "The Hunter's Path", tier = 1,
  t = "Het pad van de jager",
  d = "Hallo, jonge jager. Volgens mij ben je handig genoeg om een dier aan te kunnen en het te trainen als je maatje.$B$BJe moet naar Dazalar in Dolanaar gaan. Hij kan je op weg helpen om een eigen dier te verdienen.$b",
  o = "Praat met Dazalar in Dolanaar.",
  c = "Ja, het is tijd, $C.",
  g = { {"jager", "hunter"}, {"Volgens mij", "in my opinion, I think"}, {"handig", "skilled, handy"}, {"aan te kunnen", "to be able to handle (aankunnen)"}, {"maatje", "buddy, companion"}, {"op weg helpen", "to put on the path, help get started"}, {"verdienen", "to earn"} },
},

[12] = { en = "The People's Militia", tier = 1,
  t = "De People's Militia",
  d = "De People's Militia heeft maar één doel: de landen van Westfall verdedigen en de vrede in onze omgeving terugbrengen. Helaas is de prijs van vrede vaak bloed.$b$bEen van mijn verkenners heeft nieuws gebracht. Een groep Defias Trappers richt hier in de buurt veel schade aan. Ik heb berichten dat er Defias Trappers gezien zijn bij de Jangolode Mine in het noordwesten, en ook bij de Molsen Farm en Furlbrow's Pumpkin Farm. Wil je bij ons komen? Dood dan 15 Defias Trappers en 15 Defias Smugglers en kom daarna bij mij terug.",
  o = "Gryan Stoutmantle wil dat je 15 Defias Trappers en 15 Defias Smugglers doodt. Ga daarna terug naar hem op Sentinel Hill.",
  p = "Misschien was ik niet duidelijk, rekruut. Je moet laten zien wat je waard bent als dienaar van de People's Militia en van het Licht. Daarvoor moet je 15 Defias Trappers en 15 Defias Smugglers doden. Kom terug bij mij als dat gedaan is.",
  c = "Goed gedaan, $N. Mijn verkenner heeft je dappere daden gezien. Tot nu toe laat je heel goed zien wat je kunt.",
  g = { {"doel", "goal"}, {"verdedigen", "to defend"}, {"omgeving", "surroundings"}, {"terugbrengen", "to bring back, restore"}, {"Helaas", "unfortunately"}, {"verkenners", "scouts (verkenner)"}, {"richt ... schade aan", "wreaks havoc, causes damage (schade aanrichten)"}, {"rekruut", "recruit, pledge"}, {"waard", "worth"}, {"dienaar", "servant"}, {"dappere", "brave, valiant (dapper)"}, {"daden", "deeds, acts (daad)"} },
},

[22] = { en = "Goretusk Liver Pie", tier = 1,
  t = "Pastei met Goretusk-lever",
  d = "De uien zijn geschild. De knoflook is fijngehakt. De rozemarijn is fijngestampt. De korst is gebakken. De dille is gesneden. De jus staat te pruttelen. Nu heb ik alleen nog 8 Goretusk Livers nodig voor mijn beroemde vleespastei!",
  o = "Salma Saldean heeft 8 Goretusk Livers nodig om een Goretusk Liver Pie te maken.",
  p = "Ik heb alleen nog 8 Goretusk Livers nodig voor mijn beroemde vleespastei!",
  c = "Die zijn precies goed, $N! Heel erg bedankt. Farmer Saldean en ik gaan vanavond lekker smullen. En hier is iets kleins voor jou, voor het harde werk. Je dacht toch niet dat ik een $C zoals jij honger liet lijden?",
  g = { {"Pastei", "pie"}, {"lever", "liver"}, {"uien", "onions (ui)"}, {"geschild", "peeled (schillen)"}, {"knoflook", "garlic"}, {"fijngehakt", "minced (fijnhakken)"}, {"rozemarijn", "rosemary"}, {"fijngestampt", "crushed (fijnstampen)"}, {"korst", "crust"}, {"dille", "dill"}, {"jus", "gravy"}, {"pruttelen", "to simmer"}, {"beroemde", "famous (beroemd)"}, {"smullen", "to feast, enjoy food"}, {"honger liet lijden", "let go hungry (honger lijden)"} },
},

[64] = { en = "The Forgotten Heirloom", tier = 1,
  t = "Het vergeten erfstuk",
  d = "Het was verschrikkelijk! Verna hoorde herrie in de velden en maakte me wakker. De velden zaten vol met tuig. We gingen haastig weg en ik vergat mijn zakhorloge in te pakken. Verna's pa gaf me dat horloge op onze trouwdag. Ik word er echt ziek van dat die dieven het hebben. Ik heb het zakhorloge in de kleerkast in de boerderij laten liggen. Zoek het veld met pompoenen in het westen. Je kunt het niet missen. Als je het bij mij terugbrengt, ben ik je heel dankbaar!",
  o = "Farmer Furlbrow wil dat je zijn zakhorloge haalt. Het ligt in de kleerkast in zijn boerderij, op de pompoenboerderij in het westen.",
  p = "Je hebt mijn horloge zeker niet kunnen vinden?",
  c = "Mijn horloge! Heel erg bedankt, $gbeste meneer:beste mevrouw;!$b$bWe zijn maar arme boeren en we zijn ons land kwijt. Maar neem alsjeblieft deze beloning aan als teken van onze dank.",
  g = { {"erfstuk", "heirloom"}, {"herrie", "noise, ruckus"}, {"tuig", "riffraff, hooligans"}, {"haastig", "hastily, in a rush"}, {"zakhorloge", "pocket watch"}, {"in te pakken", "to pack (inpakken)"}, {"trouwdag", "wedding day"}, {"kleerkast", "wardrobe"}, {"pompoenen", "pumpkins (pompoen)"}, {"dankbaar", "grateful"}, {"kwijt", "lost"}, {"teken", "sign, token"} },
},

[38] = { en = "Westfall Stew", tier = 1,
  t = "Stoofpot uit Westfall",
  d = "Help me om Westfall Stew te maken! Kom terug met deze ingrediënten: $b $b 3 Stringy Vulture Meat $b 3 Goretusk Snouts $b 3 Murloc Eyes $b 3 Okra",
  o = "Salma Saldean wil 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes en 3 Okra.",
  p = "Kom terug met deze ingrediënten: $b $b 3 Stringy Vulture Meat $b 3 Goretusk Snouts $b 3 Murloc Eyes $b 3 Okra",
  c = "Die Okra maakt deze bouillon lekker dik! Nu doen we het Stringy Vulture Meat erbij, een paar Murloc Eyes en die heerlijke Goretusk Snouts. En klaar! Voor al je hulp, $N, mag jij de eerste pan Westfall Stew van vandaag hebben!",
  g = { {"Stoofpot", "stew"}, {"ingrediënten", "ingredients (ingrediënt)"}, {"bouillon", "broth"}, {"dik", "thick"}, {"doen ... erbij", "add (erbij doen)"}, {"heerlijke", "delicious (heerlijk)"}, {"pan", "pot, batch"} },
},

[4723] = { en = "Beached Sea Creature", tier = 1,
  t = "Gestrand zeedier",
  d = "Op de kust van de Mist's Edge ligt wat er over is van een enorme voshaai. Hij is veel groter dan je in Darkshore zou verwachten. Niemand weet hoe dit dier hier is gekomen. Een groep murlocs eet nu van het karkas. Maar die lijken veel te zwak om het beest te doden, zelfs met heel veel tegelijk.$B$BEen deel is al helemaal kaal gegeten. Maar er is nog genoeg over om een monster te nemen. Dat kan Gwennyth Bly'Leggonde in Auberdine dan bestuderen.",
  o = "Breng de Sea Creature Bones naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Misschien vinden we ooit een manier om te voorkomen dat deze arme dieren zinloos sterven op de kust van Darkshore. Tot die tijd moeten we doorgaan met ons onderzoek!$B$BGegroet, $N. Welk nieuws breng je?",
  c = "Weer een ontdekking. Goed gedaan, $N! Deze resten worden goed bestudeerd als ze in Darnassus zijn. Neem alsjeblieft deze kleine vergoeding aan voor de resten die je ons voor ons onderzoek hebt gegeven.",
  g = { {"Gestrand", "stranded, beached (stranden)"}, {"voshaai", "thresher shark"}, {"verwachten", "to expect"}, {"karkas", "carcass"}, {"zwak", "weak"}, {"kaal gegeten", "picked clean (kaal eten)"}, {"monster", "sample (also: monster)"}, {"bestuderen", "to study"}, {"voorkomen", "to prevent"}, {"zinloos", "needlessly, pointless"}, {"onderzoek", "research"}, {"resten", "remains (rest)"}, {"vergoeding", "fee, small payment"} },
},

[13] = { en = "The People's Militia", tier = 1,
  t = "De People's Militia",
  d = "Een groep gemene Defias Pillagers is gezien bij de Gold Coast Quarry, Moonbrook en de Alexston Farmstead. Ze plunderen daar. De People's Militia accepteert zulk gedrag niet. Ga meteen op pad, $n, en laat zien dat het Licht in Westfall is.$b$bDe Gold Coast Quarry ligt bij de kust, ten westen van de toren. Als volgende stap in je training wil ik dat je 15 van die smerige Defias Pillagers en 15 Defias Looters doodt.",
  o = "Gryan Stoutmantle wil dat je 15 Defias Pillagers en 15 Defias Looters doodt. Ga daarna terug naar hem op Sentinel Hill.",
  p = "We hebben geen tijd om te praten, $N. De Defias Pillagers nemen de mensen van Westfall de vrede en welvaart af die ze verdienen. Zorg dat er minstens 15 Defias Pillagers en 15 Defias Looters dood zijn. Dan is de boodschap duidelijk: corruptie is hier niet welkom.",
  c = "Met je dappere daden heb je tot nu toe bewezen wat je waard bent voor de People's Militia.",
  g = { {"gemene", "vicious, mean (gemeen)"}, {"plunderen", "to plunder"}, {"accepteert", "accepts (accepteren)"}, {"gedrag", "behaviour"}, {"op pad", "on your way"}, {"stap", "step"}, {"smerige", "foul, filthy (smerig)"}, {"nemen ... af", "take away from (afnemen)"}, {"welvaart", "prosperity"}, {"verdienen", "deserve"}, {"boodschap", "message"}, {"corruptie", "corruption"}, {"bewezen", "proven (bewijzen)"} },
},

[102] = { en = "Patrolling Westfall", tier = 1,
  t = "Patrouille in Westfall",
  d = "Stormwind heeft ons in de steek gelaten. Er waait een vieze wind van verdorvenheid door de vlakten van Westfall. Dit was mijn thuisland. Ik keer de burgers die hier willen blijven niet de rug toe. Wij, de vroegere boeren, gaan ons verzetten.$b$bJe taak, als je die wilt aannemen, is om te patrouilleren door de graslanden van Westfall. Spoor de gemene gnolls op en dood ze. Ze lijken samen te werken met de dieven van de Deadmines. Breng me acht Gnoll Paws, dan beloon ik je moed.",
  o = "Breng 8 Gnoll Paws naar Captain Danuvin op Sentinel Hill.",
  p = "Heb je al 8 poten van die verraderlijke gnolls verzameld?",
  c = "Goed gedaan, $N. Dappere avonturiers zoals jij vechten samen met de People's Militia. Daardoor wordt Westfall misschien weer de rijke graanschuur die het vroeger was. Neem dit alsjeblieft aan, als dank voor je onvermoeibare inzet.",
  g = { {"in de steek gelaten", "abandoned (in de steek laten)"}, {"waait", "blows (waaien)"}, {"verdorvenheid", "depravity, corruption"}, {"vlakten", "plains (vlakte)"}, {"keer ... de rug toe", "turn my back on (de rug toekeren)"}, {"burgers", "citizens (burger)"}, {"vroegere", "former (vroeger)"}, {"verzetten", "resist, make a stand (zich verzetten)"}, {"patrouilleren", "to patrol"}, {"Spoor ... op", "track down (opsporen)"}, {"beloon", "reward (belonen)"}, {"verraderlijke", "treacherous (verraderlijk)"}, {"graanschuur", "breadbasket, granary"}, {"onvermoeibare", "tireless (onvermoeibaar)"}, {"inzet", "effort, dedication"} },
},

[151] = { en = "Poor Old Blanchy", tier = 1,
  t = "Arme oude Blanchy",
  d = "Arme oude Blanchy! Ze is zo moe, na al het werk dat ze voor ons moest doen. Ik gaf haar eten en daarna gingen we weg van de boerderij. Maar we hadden niet verwacht dat de wagen kapot zou gaan. Kun je haar een paar handjes haver uit de velden brengen? Dan ben ik je heel dankbaar.$B$BIk wed dat je haver bij alle boerderijen in Westfall kunt vinden, als je uit de buurt kunt blijven van die vreselijke machines. Die hebben alles overgenomen. Ten zuidwesten van hier liggen een paar boerderijen.",
  o = "Verna Furlbrow in Westfall wil dat je haar 8 Handfuls of Oats brengt.",
  p = "De oude Blanchy kan bijna niet meer. Heb je toevallig haver voor haar gevonden?",
  c = "Heel erg bedankt, $N! Arme oude Blanchy zal zo blij zijn!",
  g = { {"Arme", "poor (arm)"}, {"verwacht", "expected (verwachten)"}, {"kapot", "broken"}, {"handjes", "handfuls (handje)"}, {"haver", "oats"}, {"Ik wed", "I bet (wedden)"}, {"uit de buurt kunt blijven van", "can steer clear of"}, {"vreselijke", "horrible (vreselijk)"}, {"overgenomen", "taken over (overnemen)"}, {"kan bijna niet meer", "is nearly at the end of her strength"} },
},

[984] = { en = "How Big a Threat?", tier = 1,
  t = "Hoe groot is het gevaar?",
  d = "Een paar van mijn broeders zijn in Teldrassil gered van een verdorven furbolg. Ik heb beloofd om nieuwe gruweldaden te stoppen. Anders raken nog meer van ons volk gewond... of erger.$B$BIk heb in Darkshore al een paar tekenen van verdorvenheid gezien. Maar ik heb nog geen tekenen gevonden dat het overal is. Ik denk dat het logisch is als het onderzoek verdergaat bij de furbolgs. Wil je een van hun kampen zoeken? Kom terug naar mij als je tekenen van verdorvenheid ziet.",
  o = "Zoek een verdorven furbolgkamp in Darkshore en ga terug naar Terenthis in Auberdine.",
  p = "Hoe gaat het zoeken, $N?",
  c = "Dit is echt verschrikkelijk nieuws, $N.$B$BDe furbolgs zijn zo dicht bij Auberdine. Dus we moeten ons voorbereiden op wat er zeker gaat komen.$B$BDank je, $N.",
  e = "Zoek een verdorven furbolgkamp",
  g = { {"broeders", "brothers, brethren (broeder)"}, {"gered", "rescued (redden)"}, {"verdorven", "corrupt"}, {"beloofd", "promised (beloven)"}, {"gruweldaden", "atrocities (gruweldaad)"}, {"gewond", "injured, wounded"}, {"tekenen", "signs (teken)"}, {"verdorvenheid", "corruption"}, {"logisch", "logical"}, {"onderzoek", "investigation, research"}, {"verschrikkelijk", "terrible"}, {"voorbereiden", "to prepare (zich voorbereiden op)"} },
},

[985] = { en = "How Big a Threat?", tier = 1,
  t = "Hoe groot is het gevaar?",
  d = "Je hebt al laten zien dat je goed bent in het verkennen van onze vijand, $N. Heb je ook wat nodig is om tegen ze te vechten?$B$BNiet alle avonturiers houden meer van een open gevecht dan van de kunst van sluipen en ontwijken.$B$BDenk je dat je deze taak aankunt? Het furbolgkamp ten zuiden van Auberdine is op dit moment het grootste gevaar voor ons volk. Daar vind je een deel van de Blackwood-stam. Dood 8 pathfinders en 5 windtalkers en kom dan hier bij mij terug.",
  o = "Dood 8 Blackwood Pathfinders en 5 Windtalkers en ga terug naar Terenthis in Auberdine.",
  p = "Aarzel niet om te doen wat moet gebeuren, kind. Ik weet hoe afschuwelijk het idee is om de wezens van het bos te doden. Maar in dit geval is het nodig. Niemand heeft een geneesmiddel gevonden tegen de verdorvenheid die over het bos is losgelaten. We moeten doen wat we kunnen om de verdorvenheid tegen te houden, tot we een geneesmiddel hebben.",
  c = "Was het bloed uit je kleren, $N, en treur niet om wat je moest doen. Wees in plaats daarvan dankbaar. Je hebt het gevaar voor ons volk hier in Auberdine kleiner gemaakt. Maar Darkshore is nog steeds in gevaar door de gevolgen van Fel Moss.",
  g = { {"verkennen", "scouting, exploring"}, {"gevecht", "fight, combat"}, {"sluipen", "sneaking, stealth"}, {"ontwijken", "evading, dodging"}, {"aankunt", "can handle (aankunnen)"}, {"stam", "tribe"}, {"Aarzel", "hesitate (aarzelen)"}, {"afschuwelijk", "horrible, repulsive"}, {"wezens", "creatures (wezen)"}, {"geneesmiddel", "cure, medicine"}, {"losgelaten", "let loose (loslaten)"}, {"tegen te houden", "to stop, to hold back (tegenhouden)"}, {"treur", "mourn (treuren)"}, {"gevolgen", "effects, consequences (gevolg)"} },
},

[1002] = { en = "Buzzbox 323", tier = 1,
  t = "Buzzbox 323",
  d = "De Buzzbox kraakt even. Dan hoor je Wizbang praten.$B$B\"De volgende Buzzbox is nummer 323. Hij staat ten noorden van Auberdine, maar... waar is het bier? Wat? O, hij staat aan de weg, dus je vindt hem makkelijk. Bij de brug.\"$B$BWizbang mompelt iets onverstaanbaars. Dan hoor je hem luid slikken.$B$B\"Deze heeft Moonstalker Fangs nodig... 6 stuks.\"",
  o = "Verzamel 6 Moonstalker Fangs en stop ze in Buzzbox 323.",
  p = "Je hebt de 6 Moonstalker Fangs er nog niet in gestopt. Toch denk je dat je binnenin geruis hoort, en onverstaanbaar gebrabbel van een gnoom. Heeft iemand anders de machine al gerepareerd?",
  c = "Plotseling komt de Buzzbox in actie. Je hoort duidelijk dat binnenin iets tanden tot stof maalt.$b$b\"Zo, je hebt het gehaald! Dat is uitstekend nieuws... Dus... Waarom ga je niet verder? O! Behalve als je nog een klus wilt!\"",
  g = { {"kraakt", "crackles (kraken)"}, {"mompelt", "mumbles (mompelen)"}, {"onverstaanbaars", "something incoherent (onverstaanbaar)"}, {"slikken", "to swallow, gulp"}, {"geruis", "static, rustling noise"}, {"gebrabbel", "babbling, ramblings"}, {"gerepareerd", "repaired (repareren)"}, {"Plotseling", "suddenly"}, {"maalt", "grinds (malen)"}, {"uitstekend", "excellent"}, {"klus", "job, task"} },
},

[1141] = { en = "The Family and the Fishing Pole", tier = 1,
  t = "De familie en de hengel",
  d = "Ik hou van vissen. De familie Blump staat bekend om vissen. Ik heet Gubber Blump. Ik vis.$B$BHier in de buurt vang ik graag een bepaalde vis. Die heet Darkshore Grouper. Vroeger ging ik met een boot vissen op tandbaars. Maar er gaan geen boten meer uit sinds die gemene ouwe murlocs hier zijn komen wonen. Ik wed dat ze ook alle tandbaarzen opeten.$B$BZeg, wil je me helpen om Darkshore Grouper te vangen? Dan geef ik je een echte Blump Family Fishing Pole! Het is een heel goede hengel om vis mee te vangen.",
  o = "Vang 6 Darkshore Grouper voor Gubber Blump in Auberdine.",
  p = "Je kunt veel lekkere gerechten maken met Darkshore Grouper. Ze zijn lekker om te eten, maar ik vind ze vangen nog leuker.$B$BHeb je al Darkshore Grouper gevangen?",
  c = "Dat zijn echt mooie tandbaarzen, $N! Bedankt voor je hulp!$B$BJe vist minstens zo goed als mijn nicht, Graun Blump. Zij heeft ook een baard en ze ruikt een beetje raar. Maar dat houdt haar niet tegen om te vissen. Volgens mij heb jij genoeg in je om een Blump Family Fishing Pole te gebruiken.",
  g = { {"hengel", "fishing pole"}, {"staat bekend om", "is known for (bekendstaan om)"}, {"bepaalde", "certain, particular (bepaald)"}, {"tandbaars", "grouper (fish)"}, {"sinds", "since"}, {"gemene", "mean, nasty (gemeen)"}, {"ouwe", "old (informal: oude)"}, {"Ik wed", "I bet (wedden)"}, {"gerechten", "dishes (gerecht)"}, {"minstens", "at least"}, {"nicht", "cousin (f.), niece"}, {"ruikt", "smells (ruiken)"}, {"houdt ... tegen", "stops (tegenhouden)"} },
},

[2118] = { en = "Plagued Lands", tier = 1,
  t = "Het zieke land",
  d = "Er gaat een ziekte door Darkshore. Hij grijpt de geest en het lichaam van alles wat hij aanraakt.$B$BDe Thistle Bears hebben het meest last van deze plaag. Ooit waren het edele dieren. Nu zijn ze een werktuig van vernietiging: hondsdol en razend. Misschien heb ik een geneesmiddel tegen deze ziekte.$B$BNeem deze val mee naar het bos en zet hem op de grond. Elke Rabid Thistle Bear die door het licht loopt, wordt een korte tijd rustig. Als de beer rustig is, volgt hij je. Breng hem dan hierheen, $N.",
  o = "Vang een levende Rabid Thistle Bear en breng hem terug naar Tharnariun.$B$BLukt het niet om een Rabid Thistle Bear te vangen en ben je je val kwijt? Ga dan terug naar Tharnariun Treetender en vraag om een nieuwe val.",
  p = "Heb je het zieke dier meegebracht, $N?$B$BLukt het niet om de val te laten werken? Maak je geen zorgen. Tharnariun's Hope is eeuwig. Heb je een nieuwe val nodig? Geef je taak dan op en meld je bij mij.",
  c = "Ons werk is pas net begonnen, $N. Ben je klaar voor je volgende taak?",
  o1 = "Rabid Thistle Bear gevangen",
  g = { {"ziekte", "sickness, disease"}, {"grijpt", "grips, seizes (grijpen)"}, {"aanraakt", "touches (aanraken)"}, {"last", "trouble (last hebben van = suffer from)"}, {"plaag", "plague"}, {"edele", "noble (edel)"}, {"werktuig", "tool, instrument"}, {"vernietiging", "destruction"}, {"hondsdol", "rabid"}, {"razend", "frenzied, furious"}, {"geneesmiddel", "cure, medicine"}, {"val", "trap"}, {"eeuwig", "eternal"}, {"Geef je taak dan op", "then abandon your task (opgeven)"}, {"meld je", "report (zich melden)"} },
},

[4681] = { en = "Washed Ashore", tier = 1,
  t = "Aangespoeld",
  d = "Dat gestrande dier is niet het enige geval hier in Darkshore. Er liggen er meer langs de kust, en zelfs in het water. Ik wil graag dat je er nog een onderzoekt. Van deze weten we waar hij ligt. Iemand heeft gemeld dat hij in het water ligt, recht ten westen van Auberdine, dicht bij een gezonken schip. Breng me alles wat je kunt vinden dat ons onderzoek kan helpen.$B$BMisschien vind je onderweg ook andere dieren. Als je iets ontdekt, vertel het ons dan zeker!",
  o = "Haal de Sea Turtle Remains bij de Skeletal Sea Turtle in het water ten westen van Auberdine. Praat daarna met Gwennyth Bly'Leggonde in Auberdine.",
  p = "Onderzoek eerst de resten van het dier in het water hier ten westen. Dan kan ik een goed verslag sturen naar de Temple of the Moon in Darnassus. Misschien zijn we dan dichter bij de reden waarom deze arme dieren ervoor kiezen om op de kust van Darkshore te stranden en te sterven.",
  c = "Je hebt ons vandaag enorm geholpen. Nu hebben we een echte kans om het raadsel op te lossen: waarom kiezen deze dieren ervoor om op de kust van Darkshore te stranden? Misschien vluchten ze weg uit het gebied rond Teldrassil. Dat idee maakt me ongerust. Kom je er onderweg nog meer tegen? Laat het me dan weten. Ons onderzoek staat hier nog maar aan het begin.$B$BNeem dit alsjeblieft aan als dank voor je moeite, namens de Temple of the Moon. Dank je, $N!",
  g = { {"Aangespoeld", "washed ashore (aanspoelen)"}, {"gestrande", "beached, stranded (stranden)"}, {"geval", "case, incident"}, {"onderzoekt", "investigate (onderzoeken)"}, {"gemeld", "reported (melden)"}, {"recht ten westen", "due west"}, {"gezonken", "sunken (zinken)"}, {"verslag", "report"}, {"reden", "reason"}, {"enorm", "enormously, hugely"}, {"raadsel", "mystery, riddle"}, {"vluchten", "flee (vluchten)"}, {"ongerust", "worried, uneasy"}, {"namens", "on behalf of"} },
},

[4728] = { en = "Beached Sea Creature", tier = 1,
  t = "Gestrand zeedier",
  d = "Op het strand ligt het lijk van een soort enorm zeezoogdier. Het is voor een deel leeggehaald. Bij dit grote gestrande dier liggen een kruiwagen en allerlei gereedschap. Iemand heeft ze achtergelaten. Het lijkt alsof iemand eerder heeft geprobeerd om het dier te onderzoeken. Murlocs hebben van het beest gegeten. Maar er is nog genoeg over om een goed monster te nemen voor Gwennyth Bly'Leggonde in Auberdine.",
  o = "Breng de Sea Creature Bones naar Gwennyth Bly'Leggonde in Auberdine.",
  p = "Opnieuw gegroet, $N! Wat brengt je terug naar Auberdine? Kom je misschien vertellen over nog een ontdekking?",
  c = "Ah, ik denk dat je er een hebt gevonden die de Explorer's League eerst onderzocht. Zij zijn hier ook in Darkshore. Ze vertelden dat ze een van de gestrande dieren onderzochten, tot de murlocs ze wegjoegen. Het lijkt erop dat jij hebt gedaan wat ons allebei niet lukte. Neem alsjeblieft deze vergoeding aan, namens de Temple of the Moon.",
  g = { {"lijk", "corpse"}, {"zeezoogdier", "sea mammal"}, {"leeggehaald", "emptied, gutted (leeghalen)"}, {"kruiwagen", "wheelbarrow"}, {"gereedschap", "tools"}, {"achtergelaten", "left behind, abandoned (achterlaten)"}, {"Het lijkt alsof", "it looks as though"}, {"monster", "sample (also: monster)"}, {"Opnieuw", "again"}, {"gegroet", "greetings (groeten)"}, {"wegjoegen", "chased away (wegjagen)"}, {"lukte", "succeeded, worked out (lukken)"}, {"vergoeding", "fee, small payment"} },
},

[4811] = { en = "The Red Crystal", tier = 1,
  t = "Het rode kristal",
  d = "Ten oosten van ons lopen vijandige moonkin rond, en het worden er steeds meer. Vroeger dachten we dat het vriendelijke, bijna mystieke wezens waren. Sommigen hebben nog steeds veel respect voor ze. Maar ik moet aan de veiligheid van Auberdine denken. Daarom kijk ik er realistischer naar.$B$BIk heb berichten gekregen dat een groot rood kristal de moonkin aantrekt. Het ligt langs de bergketen in het oosten van Darkshore. Niemand weet wat dat kristal is. Niemand weet zelfs of het echt bestaat. Ik wil dat je het daar zoekt. Kom me dan vertellen wat je vindt.",
  o = "Reis naar het oosten van Auberdine en zoek een groot, rood kristal langs de bergketen in het oosten van Darkshore. Vertel Sentinel Glynda Nal'Shea in Auberdine wat je vindt.",
  p = "Wat kun je me vertellen over dat rode kristal? Bestaat het eigenlijk wel?",
  c = "Dus het kristal bestaat, $N? Heel interessant... maar goed, je hebt je taak goed uitgevoerd. Goed werk!$B$BWat is dit kristal precies? Dat is maar één vraag in een zee van vragen. Ik heb ook een andere vraag: waarom trekt dit ding de moonkin aan? Is het kristal onschuldig? Of heeft het een kwaadaardiger doel?$B$BIk heb nog veel meer vragen. Maar we moeten dat kristal goed van dichtbij bekijken. Pas dan krijgen we antwoorden.",
  e = "Zoek het grote, rode kristal op de bergketen in het oosten van Darkshore",
  g = { {"vijandige", "hostile (vijandig)"}, {"mystieke", "mystical (mystiek)"}, {"wezens", "creatures (wezen)"}, {"respect", "respect, reverence"}, {"veiligheid", "safety"}, {"realistischer", "more realistically (realistisch)"}, {"berichten", "reports, messages (bericht)"}, {"aantrekt", "attracts, draws (aantrekken)"}, {"bergketen", "mountain range"}, {"bestaat", "exists (bestaan)"}, {"uitgevoerd", "carried out, executed (uitvoeren)"}, {"onschuldig", "harmless, innocent"}, {"kwaadaardiger", "more sinister (kwaadaardig)"}, {"doel", "purpose, goal"}, {"van dichtbij", "up close"} },
},

[4812] = { en = "As Water Cascades", tier = 1,
  t = "Als water omlaag stroomt",
  d = "Neem dit lege flesje en vul het met water uit de maanbron hier in Auberdine. Zulke sterke magie zou ons een aanwijzing moeten geven over waar het kristal van gemaakt is. Daarvoor giet je het water over het kristal. De rest gaat dan vanzelf.$B$BIk verwacht niet dat er iets ergs met je gebeurt. Toch wil ik dat je voorzichtig bent. Boven ons, in het oosten, ligt Felwood. Ik denk dat het kristal met die plek verbonden is. Als dat zo is, kan het heel gevaarlijk zijn.",
  o = "Vul de Empty Water Tube bij de maanbron van Auberdine. Onderzoek daarna het rode kristal langs de bergwand in het oosten van Darkshore.",
  p = "Het kristal ziet er heel vreemd uit tussen de bossen van Darkshore. Je denkt dat je een heel zacht gezoem hoort, diep van binnenuit.",
  c = "Je bent weer bij het geheimzinnige kristal. Je haalt de stop van de buis met maanbronwater. Voorzichtig giet je het water over de bovenkant van het kristal. Het water stroomt langs het kristalrooster naar beneden. Dan zie je het troebele oppervlak doorzichtig worden...",
  g = { {"omlaag", "down, downward"}, {"stroomt", "flows, cascades (stromen)"}, {"flesje", "small bottle, vial (fles)"}, {"maanbron", "moonwell"}, {"aanwijzing", "clue"}, {"giet", "pour (gieten)"}, {"vanzelf", "by itself"}, {"verbonden", "tied, connected (verbinden)"}, {"bergwand", "mountain wall"}, {"gezoem", "humming, buzzing"}, {"geheimzinnige", "mysterious (geheimzinnig)"}, {"stop", "stopper, plug"}, {"kristalrooster", "crystal lattice"}, {"troebele", "cloudy, opaque (troebel)"}, {"oppervlak", "surface"}, {"doorzichtig", "transparent"} },
},

[4813] = { en = "The Fragments Within", tier = 1,
  t = "De stukjes binnenin",
  d = "Het maanbronwater laat zien dat er binnen in het kristal een paar kleine stukjes bot zitten. Er zit ook een halve kaak in. De kaak lijkt van een mensachtig wezen te zijn. Maar je weet het niet zeker zonder het kristal open te breken. En dat is bijna onmogelijk, zelfs voor de sterkste magie.$B$BJe taak is klaar. Je hoeft alleen nog verslag uit te brengen bij Sentinel Glynda Nal'Shea in Auberdine.",
  o = "Vertel Sentinel Glynda Nal'Shea in Auberdine wat je hebt gevonden.",
  c = "Nou, het lijkt erop dat we nu meer over dit kristal weten. Maar het resultaat is: nog meer vragen zonder antwoord!$B$BIk breng wat je hebt ontdekt naar de raad hier in Auberdine. Misschien weten zij wat we met dit kristal moeten doen. Tenminste, als we er iets mee moeten doen. Voor nu is het gevaar ver genoeg naar het oosten. Het kan ons hier geen kwaad doen.$B$BEn wat jou betreft: neem dit alsjeblieft. Zie het als een beloning voor goed werk, $N.",
  g = { {"binnenin", "inside, within"}, {"bot", "bone"}, {"kaak", "jaw, jawbone"}, {"mensachtig", "humanoid, human-like"}, {"wezen", "creature, being"}, {"zonder", "without"}, {"onmogelijk", "impossible"}, {"verslag uit te brengen", "to report (verslag uitbrengen)"}, {"resultaat", "result"}, {"ontdekt", "discovered (ontdekken)"}, {"raad", "council"}, {"Tenminste", "at least"}, {"kwaad", "harm"}, {"wat jou betreft", "as for you"} },
},

})

